-- VTech Dependency Tracker — core schema
-- Owner: Claude (architect). Other agents: do NOT edit this file; add a new numbered migration and get it reviewed.
--
-- Model in one paragraph:
--   master_dependencies = VTech's years-old checklist (per agency type).
--   A project picks some of them (project_dependencies) and may add custom ones.
--   Each picked dependency is applied to a chosen set of rooms -> dependency_items (the grid).
--   A site_visit records visit_checks (complete/pending/na + date) against items.
--   finalize_visit() writes checks onto items. The app then builds one dispatch per agency per channel
--   listing ALL currently pending items for that agency. mark_dispatch_sent() bumps reminder counts.
--   Escalation level is derived from reminder number vs the project's thresholds (computed in lib/escalation.ts).

create extension if not exists pgcrypto;

-- ───────────────────────── enums ─────────────────────────
create type public.app_role        as enum ('super_admin', 'pm_lead', 'pm');
create type public.item_status     as enum ('unchecked', 'pending', 'complete', 'na');
create type public.visit_status    as enum ('draft', 'finalized', 'sent');
create type public.dispatch_channel as enum ('email', 'whatsapp');
create type public.dispatch_status as enum ('draft', 'sent', 'failed', 'skipped');

-- ───────────────────────── people ─────────────────────────
create table public.profiles (
  id          uuid primary key references auth.users (id) on delete cascade,
  full_name   text not null,
  email       text not null unique,
  phone       text,
  role        public.app_role not null default 'pm',
  active      boolean not null default true,
  created_at  timestamptz not null default now()
);

-- ───────────────────────── master catalogue ─────────────────────────
create table public.agency_types (
  id          uuid primary key default gen_random_uuid(),
  name        text not null,
  sort        int  not null default 0,
  created_at  timestamptz not null default now()
);
create unique index agency_types_name_uq on public.agency_types (lower(name));

create table public.master_dependencies (
  id              uuid primary key default gen_random_uuid(),
  agency_type_id  uuid not null references public.agency_types (id),
  seq             int  not null,
  text            text not null,
  active          boolean not null default true,
  origin          text not null default 'master' check (origin in ('master', 'proposed', 'promoted')),
  source_note     text,
  created_by      uuid references public.profiles (id),
  created_at      timestamptz not null default now()
);
create unique index master_dependencies_text_uq on public.master_dependencies (agency_type_id, lower(text));

create table public.app_settings (
  key         text primary key,
  value       jsonb not null,
  updated_at  timestamptz not null default now()
);

-- ───────────────────────── projects ─────────────────────────
create table public.projects (
  id             uuid primary key default gen_random_uuid(),
  name           text not null,
  client_name    text,
  site_address   text,
  status         text not null default 'active' check (status in ('active', 'on_hold', 'closed')),
  -- Escalation policy (decided per project by PM + management at setup).
  -- Reminder n goes to L1 while n <= l2_after, L2 while n <= l3_after, else L3.
  l2_after       int  not null default 3 check (l2_after >= 1),
  l3_after       int  not null default 6,
  -- Management (super admins) are CC'd on emails once the dispatch level >= mgmt_cc_level. 4 = never.
  mgmt_cc_level  int  not null default 3 check (mgmt_cc_level between 1 and 4),
  terms          text not null default '',
  created_by     uuid references public.profiles (id) default auth.uid(),
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  check (l3_after > l2_after)
);

create table public.project_members (
  project_id  uuid not null references public.projects (id) on delete cascade,
  user_id     uuid not null references public.profiles (id) on delete cascade,
  added_at    timestamptz not null default now(),
  primary key (project_id, user_id)
);

create table public.floors (
  id          uuid primary key default gen_random_uuid(),
  project_id  uuid not null references public.projects (id) on delete cascade,
  label       text not null,
  sort        int  not null default 0,
  unique (id, project_id),
  unique (project_id, label)
);

create table public.rooms (
  id          uuid primary key default gen_random_uuid(),
  project_id  uuid not null,
  floor_id    uuid not null,
  name        text not null,
  sort        int  not null default 0,
  unique (id, project_id),
  unique (floor_id, name),
  foreign key (floor_id, project_id) references public.floors (id, project_id) on delete cascade
);

create table public.agencies (
  id                  uuid primary key default gen_random_uuid(),
  project_id          uuid not null references public.projects (id) on delete cascade,
  agency_type_id      uuid not null references public.agency_types (id),
  company_name        text not null,
  escalation_enabled  boolean not null default true,
  notes               text,
  created_at          timestamptz not null default now(),
  unique (id, project_id)
);

create table public.agency_contacts (
  id           uuid primary key default gen_random_uuid(),
  project_id   uuid not null,
  agency_id    uuid not null,
  name         text not null,
  designation  text not null,
  level        int  not null check (level between 1 and 3),  -- 1 = junior/site engineer … 3 = owner/head
  phone        text,
  email        text,
  active       boolean not null default true,
  created_at   timestamptz not null default now(),
  check (phone is not null or email is not null),
  foreign key (agency_id, project_id) references public.agencies (id, project_id) on delete cascade
);

create table public.project_dependencies (
  id                    uuid primary key default gen_random_uuid(),
  project_id            uuid not null references public.projects (id) on delete cascade,
  master_dependency_id  uuid references public.master_dependencies (id),   -- null = custom to this project
  agency_type_id        uuid not null references public.agency_types (id),
  text                  text not null,
  seq                   int  not null default 0,
  created_by            uuid references public.profiles (id) default auth.uid(),
  created_at            timestamptz not null default now(),
  unique (id, project_id),
  unique (project_id, master_dependency_id)
);

create table public.dependency_items (
  id                      uuid primary key default gen_random_uuid(),
  project_id              uuid not null,
  room_id                 uuid not null,
  project_dependency_id   uuid not null,
  agency_id               uuid,
  status                  public.item_status not null default 'unchecked',
  first_raised_on         date,
  completed_on            date,
  reminder_count          int  not null default 0,
  last_reminded_on        date,
  last_reminded_visit_id  uuid,
  note                    text,
  photo_path              text,
  updated_by              uuid references public.profiles (id),
  updated_at              timestamptz not null default now(),
  unique (id, project_id),
  unique (room_id, project_dependency_id),
  foreign key (room_id, project_id) references public.rooms (id, project_id) on delete cascade,
  foreign key (project_dependency_id, project_id) references public.project_dependencies (id, project_id) on delete cascade,
  foreign key (agency_id, project_id) references public.agencies (id, project_id) on delete set null (agency_id)
);
create index dependency_items_project_status_idx on public.dependency_items (project_id, status);

create table public.site_visits (
  id            uuid primary key default gen_random_uuid(),
  project_id    uuid not null references public.projects (id) on delete cascade,
  pm_id         uuid not null references public.profiles (id) default auth.uid(),
  visit_date    date not null default ((now() at time zone 'Asia/Kolkata')::date),
  status        public.visit_status not null default 'draft',
  finalized_at  timestamptz,
  created_at    timestamptz not null default now(),
  unique (id, project_id)
);

create table public.visit_checks (
  id           uuid primary key default gen_random_uuid(),
  project_id   uuid not null,
  visit_id     uuid not null,
  item_id      uuid not null,
  status       public.item_status not null check (status <> 'unchecked'),
  status_date  date not null,                 -- completion date, or date observed pending
  note         text,
  photo_path   text,
  checked_by   uuid references public.profiles (id) default auth.uid(),
  checked_at   timestamptz not null default now(),
  unique (visit_id, item_id),
  foreign key (visit_id, project_id) references public.site_visits (id, project_id) on delete cascade,
  foreign key (item_id, project_id) references public.dependency_items (id, project_id) on delete cascade
);

create table public.dispatches (
  id            uuid primary key default gen_random_uuid(),
  project_id    uuid not null,
  visit_id      uuid not null,
  agency_id     uuid not null,
  channel       public.dispatch_channel not null,
  level         int  not null check (level between 1 and 3),
  recipients    jsonb not null default '{}'::jsonb,  -- {to:[{name,email|phone}], cc:[...]}
  subject       text,
  body_text     text not null,
  body_html     text,
  status        public.dispatch_status not null default 'draft',
  sent_at       timestamptz,
  sent_by       uuid references public.profiles (id),
  provider_ref  text,
  error         text,
  created_at    timestamptz not null default now(),
  unique (visit_id, agency_id, channel),
  foreign key (visit_id, project_id) references public.site_visits (id, project_id) on delete cascade,
  foreign key (agency_id, project_id) references public.agencies (id, project_id) on delete cascade
);

create table public.dispatch_items (
  dispatch_id  uuid not null references public.dispatches (id) on delete cascade,
  item_id      uuid not null references public.dependency_items (id) on delete cascade,
  reminder_no  int  not null,
  level        int  not null,
  primary key (dispatch_id, item_id)
);

-- ───────────────────────── auth helpers ─────────────────────────
create function public.my_role() returns public.app_role
language sql stable security definer set search_path = public as $$
  select role from public.profiles where id = auth.uid() and active
$$;

create function public.is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(public.my_role() in ('super_admin', 'pm_lead'), false)
$$;

create function public.is_super_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(public.my_role() = 'super_admin', false)
$$;

create function public.can_access_project(p uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select public.is_admin()
      or exists (
           select 1 from public.project_members m
           join public.profiles pr on pr.id = m.user_id and pr.active
           where m.project_id = p and m.user_id = auth.uid()
         )
$$;

-- ───────────────────────── triggers ─────────────────────────
create function public.tg_projects_defaults() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.terms is null or new.terms = '' then
    select coalesce(value #>> '{}', '') into new.terms from public.app_settings where key = 'default_terms';
    new.terms := coalesce(new.terms, '');
  end if;
  new.updated_at := now();
  return new;
end $$;
create trigger projects_defaults before insert or update on public.projects
  for each row execute function public.tg_projects_defaults();

-- Creator of a project is automatically a member (so a PM can set up a project and keep seeing it).
create function public.tg_projects_add_creator() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.created_by is not null then
    insert into public.project_members (project_id, user_id) values (new.id, new.created_by)
    on conflict do nothing;
  end if;
  return new;
end $$;
create trigger projects_add_creator after insert on public.projects
  for each row execute function public.tg_projects_add_creator();

-- When an agency is added, assign it to unassigned items of the same agency type.
create function public.tg_agencies_assign_items() returns trigger
language plpgsql security invoker set search_path = public as $$
begin
  update public.dependency_items i
     set agency_id = new.id
    from public.project_dependencies d
   where i.project_id = new.project_id
     and i.agency_id is null
     and d.id = i.project_dependency_id
     and d.agency_type_id = new.agency_type_id;
  return new;
end $$;
create trigger agencies_assign_items after insert on public.agencies
  for each row execute function public.tg_agencies_assign_items();

-- ───────────────────────── RPCs (security invoker: RLS still applies) ─────────────────────────

-- Copy chosen master dependencies into a project.
create function public.add_master_dependencies(p_project uuid, p_master_ids uuid[]) returns int
language plpgsql security invoker set search_path = public as $$
declare n int;
begin
  insert into public.project_dependencies (project_id, master_dependency_id, agency_type_id, text, seq)
  select p_project, m.id, m.agency_type_id, m.text, m.seq
    from public.master_dependencies m
   where m.id = any (p_master_ids)
  on conflict (project_id, master_dependency_id) do nothing;
  get diagnostics n = row_count;
  return n;
end $$;

-- Apply project dependencies to rooms (cross product). Idempotent.
create function public.apply_dependencies(p_project uuid, p_dep_ids uuid[], p_room_ids uuid[]) returns int
language plpgsql security invoker set search_path = public as $$
declare n int;
begin
  insert into public.dependency_items (project_id, room_id, project_dependency_id, agency_id)
  select p_project, r.id, d.id,
         (select a.id from public.agencies a
           where a.project_id = p_project and a.agency_type_id = d.agency_type_id
           order by a.created_at limit 1)
    from public.rooms r
    cross join public.project_dependencies d
   where r.project_id = p_project and r.id = any (p_room_ids)
     and d.project_id = p_project and d.id = any (p_dep_ids)
  on conflict (room_id, project_dependency_id) do nothing;
  get diagnostics n = row_count;
  return n;
end $$;

-- Duplicate a floor (rooms + their applied dependencies, reset to unchecked).
create function public.copy_floor(p_floor uuid, p_label text) returns uuid
language plpgsql security invoker set search_path = public as $$
declare f public.floors; nf uuid;
begin
  select * into f from public.floors where id = p_floor;
  if not found then raise exception 'floor not found or no access'; end if;

  insert into public.floors (project_id, label, sort)
  values (f.project_id, p_label,
          (select coalesce(max(sort), 0) + 1 from public.floors where project_id = f.project_id))
  returning id into nf;

  insert into public.rooms (project_id, floor_id, name, sort)
  select f.project_id, nf, name, sort from public.rooms where floor_id = p_floor;

  insert into public.dependency_items (project_id, room_id, project_dependency_id, agency_id)
  select f.project_id, nr.id, i.project_dependency_id, i.agency_id
    from public.dependency_items i
    join public.rooms r  on r.id = i.room_id and r.floor_id = p_floor
    join public.rooms nr on nr.floor_id = nf and nr.name = r.name;

  return nf;
end $$;

-- Write a visit's checks onto the items. Only the PM's physical verification closes items.
create function public.finalize_visit(p_visit uuid) returns int
language plpgsql security invoker set search_path = public as $$
declare v public.site_visits; n int;
begin
  select * into v from public.site_visits where id = p_visit for update;
  if not found then raise exception 'visit not found or no access'; end if;
  if v.status <> 'draft' then raise exception 'visit already %', v.status; end if;

  update public.dependency_items i set
    status          = c.status,
    -- (re)raised: new pending episode starts at the observed date, counter restarts
    first_raised_on = case when c.status = 'pending' and i.status <> 'pending' then c.status_date
                           when c.status = 'pending' then coalesce(i.first_raised_on, c.status_date)
                           else i.first_raised_on end,
    reminder_count  = case when c.status = 'pending' and i.status <> 'pending' then 0
                           else i.reminder_count end,
    completed_on    = case when c.status = 'complete' then c.status_date else null end,
    note            = coalesce(c.note, i.note),
    photo_path      = coalesce(c.photo_path, i.photo_path),
    updated_by      = auth.uid(),
    updated_at      = now()
  from public.visit_checks c
  where c.visit_id = p_visit and c.item_id = i.id;
  get diagnostics n = row_count;

  update public.site_visits set status = 'finalized', finalized_at = now() where id = p_visit;
  return n;
end $$;

-- Mark a dispatch as sent. Reminder count increments once per item per visit,
-- even if both email and WhatsApp go out for the same visit.
create function public.mark_dispatch_sent(p_dispatch uuid, p_ref text default null) returns void
language plpgsql security invoker set search_path = public as $$
declare d public.dispatches;
begin
  select * into d from public.dispatches where id = p_dispatch for update;
  if not found then raise exception 'dispatch not found or no access'; end if;
  if d.status = 'sent' then return; end if;

  update public.dispatches
     set status = 'sent', sent_at = now(), sent_by = auth.uid(), provider_ref = p_ref, error = null
   where id = p_dispatch;

  update public.dependency_items i
     set reminder_count         = i.reminder_count + 1,
         last_reminded_on       = (now() at time zone 'Asia/Kolkata')::date,
         last_reminded_visit_id = d.visit_id
    from public.dispatch_items di
   where di.dispatch_id = p_dispatch
     and di.item_id = i.id
     and i.status = 'pending'
     and i.last_reminded_visit_id is distinct from d.visit_id;

  if not exists (select 1 from public.dispatches where visit_id = d.visit_id and status = 'draft') then
    update public.site_visits set status = 'sent' where id = d.visit_id;
  end if;
end $$;

create function public.mark_dispatch_failed(p_dispatch uuid, p_error text) returns void
language sql security invoker set search_path = public as $$
  update public.dispatches set status = 'failed', error = p_error where id = p_dispatch and status <> 'sent';
$$;

-- Promote a project-specific dependency into the master list (admins only).
create function public.promote_dependency(p_project_dependency uuid) returns uuid
language plpgsql security invoker set search_path = public as $$
declare d public.project_dependencies; mid uuid;
begin
  if not public.is_admin() then raise exception 'only admins can edit the master list'; end if;
  select * into d from public.project_dependencies where id = p_project_dependency;
  if not found then raise exception 'not found'; end if;
  if d.master_dependency_id is not null then return d.master_dependency_id; end if;

  insert into public.master_dependencies (agency_type_id, seq, text, origin, source_note, created_by)
  values (d.agency_type_id,
          (select coalesce(max(seq), 0) + 1 from public.master_dependencies where agency_type_id = d.agency_type_id),
          d.text, 'promoted', 'promoted from project ' || d.project_id, auth.uid())
  returning id into mid;

  update public.project_dependencies set master_dependency_id = mid where id = d.id;
  return mid;
end $$;

-- ───────────────────────── RLS ─────────────────────────
alter table public.profiles             enable row level security;
alter table public.agency_types         enable row level security;
alter table public.master_dependencies  enable row level security;
alter table public.app_settings         enable row level security;
alter table public.projects             enable row level security;
alter table public.project_members      enable row level security;
alter table public.floors               enable row level security;
alter table public.rooms                enable row level security;
alter table public.agencies             enable row level security;
alter table public.agency_contacts      enable row level security;
alter table public.project_dependencies enable row level security;
alter table public.dependency_items     enable row level security;
alter table public.site_visits          enable row level security;
alter table public.visit_checks         enable row level security;
alter table public.dispatches           enable row level security;
alter table public.dispatch_items       enable row level security;

-- profiles: read self or (admin). Writes: super_admin any; pm_lead only PM rows and cannot promote.
-- Inserts happen server-side with the service role (app/api/admin/users).
create policy profiles_read on public.profiles for select to authenticated
  using (id = auth.uid() or public.is_admin());
create policy profiles_super_write on public.profiles for update to authenticated
  using (public.is_super_admin()) with check (public.is_super_admin());
create policy profiles_lead_write on public.profiles for update to authenticated
  using (public.my_role() = 'pm_lead' and role = 'pm') with check (role = 'pm');

-- catalogue: everyone signed in reads; admins write.
create policy agency_types_read  on public.agency_types for select to authenticated using (true);
create policy agency_types_write on public.agency_types for all    to authenticated
  using (public.is_admin()) with check (public.is_admin());
create policy master_read  on public.master_dependencies for select to authenticated using (true);
create policy master_write on public.master_dependencies for all    to authenticated
  using (public.is_admin()) with check (public.is_admin());
create policy settings_read  on public.app_settings for select to authenticated using (true);
create policy settings_write on public.app_settings for all    to authenticated
  using (public.is_super_admin()) with check (public.is_super_admin());

-- projects: anyone can create (becomes member); members/admins read+update; super admin deletes.
create policy projects_read   on public.projects for select to authenticated using (public.can_access_project(id));
create policy projects_insert on public.projects for insert to authenticated with check (created_by = auth.uid());
create policy projects_update on public.projects for update to authenticated
  using (public.can_access_project(id)) with check (public.can_access_project(id));
create policy projects_delete on public.projects for delete to authenticated using (public.is_super_admin());

-- membership: read if you can see the project; only admins assign PMs.
create policy members_read  on public.project_members for select to authenticated using (public.can_access_project(project_id));
create policy members_write on public.project_members for all    to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- everything inside a project: full access if you can access the project
do $$
declare t text;
begin
  foreach t in array array['floors','rooms','agencies','agency_contacts','project_dependencies',
                           'dependency_items','site_visits','visit_checks','dispatches']
  loop
    execute format(
      'create policy %I on public.%I for all to authenticated
         using (public.can_access_project(project_id)) with check (public.can_access_project(project_id))',
      t || '_project_access', t);
  end loop;
end $$;

create policy dispatch_items_access on public.dispatch_items for all to authenticated
  using (exists (select 1 from public.dispatches d where d.id = dispatch_id and public.can_access_project(d.project_id)))
  with check (exists (select 1 from public.dispatches d where d.id = dispatch_id and public.can_access_project(d.project_id)));

-- ───────────────────────── grants ─────────────────────────
revoke all on all functions in schema public from public, anon;
grant execute on all functions in schema public to authenticated, service_role;
